// Generates the Android launcher icons from the desktop mark.
//
// The APK was shipping Capacitor's stock icon while the desktop app used
// desktop/icons/icon.png — the same product with two faces. Rather than export
// a PNG and resize it, this redraws the mark at every density from the same
// geometry desktop/icons/make-icon.js uses, so the two can never drift: a ring
// and a dot in cream on a charcoal plate. Same encoder approach too — a
// hand-rolled PNG over zlib, no image dependencies.
//
// mobile/android is generated by `cap add android` and gitignored, so this
// runs after generation, alongside patch-android-manifest.mjs.
//
// usage: node scripts/make-android-icons.mjs
import fs from 'node:fs';
import path from 'node:path';
import zlib from 'node:zlib';
import { fileURLToPath } from 'node:url';

const ROOT = path.join(path.dirname(fileURLToPath(import.meta.url)), '..');
const RES = path.join(ROOT, 'mobile', 'android', 'app', 'src', 'main', 'res');

const BG = [28, 27, 25];      // #1c1b19 charcoal
const FG = [245, 241, 221];   // #f5f1dd cream

// Legacy launcher bitmaps, and the adaptive foreground. Adaptive icons are
// 108dp with only the central 72dp guaranteed visible — the rest is what the
// launcher's mask crops away — so the foreground is drawn separately at 1.5x
// the legacy size rather than reusing the square art.
const LEGACY = { mdpi: 48, hdpi: 72, xhdpi: 96, xxhdpi: 144, xxxhdpi: 192 };
const FOREGROUND = { mdpi: 108, hdpi: 162, xhdpi: 216, xxhdpi: 324, xxxhdpi: 432 };
const SAFE = 72 / 108;        // the fraction of the foreground a mask may keep

/* ---------- PNG encoding ---------- */

function crc32(buf) {
  const table = crc32.t || (crc32.t = (() => {
    const t = [];
    for (let n = 0; n < 256; n++) {
      let c = n;
      for (let k = 0; k < 8; k++) c = c & 1 ? 0xedb88320 ^ (c >>> 1) : c >>> 1;
      t[n] = c;
    }
    return t;
  })());
  let crc = 0xffffffff;
  for (let i = 0; i < buf.length; i++) crc = table[(crc ^ buf[i]) & 0xff] ^ (crc >>> 8);
  return (crc ^ 0xffffffff) >>> 0;
}

function chunk(type, data) {
  const t = Buffer.from(type, 'ascii');
  const len = Buffer.alloc(4); len.writeUInt32BE(data.length, 0);
  const crc = Buffer.alloc(4); crc.writeUInt32BE(crc32(Buffer.concat([t, data])), 0);
  return Buffer.concat([len, t, data, crc]);
}

// paint(x, y) -> [r, g, b, a]
function png(size, paint) {
  const raw = Buffer.alloc(size * (1 + size * 4));
  for (let y = 0; y < size; y++) {
    const row = y * (1 + size * 4);
    raw[row] = 0;                       // filter: none
    for (let x = 0; x < size; x++) {
      const px = paint(x, y);
      const o = row + 1 + x * 4;
      raw[o] = px[0]; raw[o + 1] = px[1]; raw[o + 2] = px[2]; raw[o + 3] = px[3];
    }
  }
  const ihdr = Buffer.alloc(13);
  ihdr.writeUInt32BE(size, 0);
  ihdr.writeUInt32BE(size, 4);
  ihdr[8] = 8;   // bit depth
  ihdr[9] = 6;   // RGBA
  return Buffer.concat([
    Buffer.from([137, 80, 78, 71, 13, 10, 26, 10]),
    chunk('IHDR', ihdr),
    chunk('IDAT', zlib.deflateSync(raw, { level: 9 })),
    chunk('IEND', Buffer.alloc(0))
  ]);
}

/* ---------- the mark ---------- */

// Coverage-based antialiasing: each pixel is sampled on a 3x3 grid so the ring
// and the plate corners read smooth rather than stair-stepped. At mdpi the
// whole icon is 48px across, where aliasing is the difference between a mark
// and a smudge.
function coverage(x, y, test) {
  let hits = 0;
  for (let sy = 0; sy < 3; sy++) {
    for (let sx = 0; sx < 3; sx++) {
      if (test(x + (sx + 0.5) / 3, y + (sy + 0.5) / 3)) hits++;
    }
  }
  return hits / 9;
}

// Ring plus dot, in the plate's own coordinate space: `s` is the plate size and
// (ox, oy) its top-left. Identical proportions to desktop/icons/make-icon.js.
function glyph(px, py, s, ox, oy) {
  const cx = ox + s / 2;
  const cy = oy + s / 2 - s * 0.045;
  const d = Math.hypot(px - cx, py - cy);
  const ring = d <= s * 0.30 && d >= s * 0.30 - s * 0.055;
  const dot = Math.hypot(px - cx, py - (cy + s * 0.30 + s * 0.085)) <= s * 0.045;
  return ring || dot;
}

function roundedRect(px, py, s, r) {
  const x = Math.min(px, s - px);
  const y = Math.min(py, s - py);
  if (x > r || y > r) return px >= 0 && px <= s && py >= 0 && py <= s;
  const dx = r - x, dy = r - y;
  return dx * dx + dy * dy <= r * r;
}

// Cream glyph over a charcoal plate, the plate's own alpha premultiplied in so
// the corners stay clean against any launcher wallpaper.
function plated(size, inPlate) {
  return (x, y) => {
    const bgA = coverage(x, y, inPlate);
    const fgA = coverage(x, y, (a, b) => glyph(a, b, size, 0, 0)) * bgA;
    return [
      Math.round(BG[0] * (1 - fgA) + FG[0] * fgA),
      Math.round(BG[1] * (1 - fgA) + FG[1] * fgA),
      Math.round(BG[2] * (1 - fgA) + FG[2] * fgA),
      Math.round(255 * bgA)
    ];
  };
}

/* The adaptive foreground: the glyph alone on transparency, scaled to sit
 * inside the 72dp safe circle. Drawn at a virtual plate size chosen so the
 * mark's bounding box fits with a little air:
 *
 *   vertical extent   0.155s (ring top) .. 0.885s (dot bottom)  = 0.73s
 *   bbox centre       0.52s
 *
 * A virtual plate of 0.78 x canvas puts the mark at 0.57 of the canvas, i.e.
 * about 61dp — Material's keyline for a circular mark, and comfortably inside
 * the 0.667 a mask keeps. Filling the safe zone exactly (0.87, ~69dp) fits,
 * but the ring then kisses the mask edge and reads visibly heavier than the
 * stock icons beside it in the launcher.
 *
 * Centring uses the bbox centre, not the plate centre — the dot hangs below
 * the ring, and centring the plate would leave the mark sitting high.
 */
function foreground(size) {
  const v = size * 0.78;
  const ox = size / 2 - v * 0.5;
  const oy = size / 2 - v * 0.52;
  return (x, y) => {
    const a = coverage(x, y, (px, py) => glyph(px, py, v, ox, oy));
    return [FG[0], FG[1], FG[2], Math.round(255 * a)];
  };
}

/* ---------- write ---------- */

let written = 0;
function put(dir, name, buf) {
  const target = path.join(RES, dir);
  if (!fs.existsSync(target)) fs.mkdirSync(target, { recursive: true });
  fs.writeFileSync(path.join(target, name), buf);
  written += 1;
}

if (!fs.existsSync(RES)) {
  console.error('✗ mobile/android/app/src/main/res is missing — run `npx cap add android` first.');
  process.exit(1);
}

for (const [density, size] of Object.entries(LEGACY)) {
  put(`mipmap-${density}`, 'ic_launcher.png',
    png(size, plated(size, (x, y) => roundedRect(x, y, size, size * 0.22))));
  // The round variant is a real circle, not the square masked at display time:
  // launchers that ask for it expect art drawn to the circle's edge.
  put(`mipmap-${density}`, 'ic_launcher_round.png',
    png(size, plated(size, (x, y) => Math.hypot(x - size / 2, y - size / 2) <= size / 2)));
}

for (const [density, size] of Object.entries(FOREGROUND)) {
  put(`mipmap-${density}`, 'ic_launcher_foreground.png', png(size, foreground(size)));
}

// The adaptive background is a flat colour rather than art, so the launcher can
// parallax and mask it however it likes without the plate's edge showing.
// Capacitor's template ships this as white.
put('values', 'ic_launcher_background.xml',
  Buffer.from('<?xml version="1.0" encoding="utf-8"?>\n<resources>\n' +
    '    <color name="ic_launcher_background">#1C1B19</color>\n</resources>\n', 'utf8'));

console.log(`✓ ${written} launcher assets written from the desktop mark (safe zone ${(SAFE * 100).toFixed(0)}%)`);
